// src/components/templates/portfolio/canvas.tsx
// ALL 5 PORTFOLIO TEMPLATES
// Research basis: Awwwards 2024-2025 winners, Webby Award nominees
// Canvas: Clean editorial white — suits designers, creatives, SMEs
// Studio: Dark cinematic — suits photographers, filmmakers, agencies
// Forge: Developer terminal — suits engineers, open source contributors
// Spectrum: Bold color-block — suits creative directors, brand designers
// Blueprint: Technical grid — suits architects, engineers, consultants

import Image from "next/image";
import Link from "next/link";
import type { PortfolioData } from "@/lib/validators/template-schemas";

interface PortfolioProps { data: PortfolioData; accentColor?: string; }

// ─────────────────────────────────────────────────────────────────────────────
// SHARED HELPERS
// ─────────────────────────────────────────────────────────────────────────────

function Arrow({ size = 16, className = "" }: { size?: number; className?: string }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor"
      strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}>
      <path d="M7 17L17 7M7 7h10v10" />
    </svg>
  );
}

function ExternalArrow({ size = 14 }: { size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor"
      strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M18 13v6a2 2 0 01-2 2H5a2 2 0 01-2-2V8a2 2 0 012-2h6M15 3h6v6M10 14L21 3" />
    </svg>
  );
}

function contactHref(type: string, value: string) {
  if (type === "email") return `mailto:${value}`;
  if (type === "phone") return `tel:${value.replace(/\s/g, "")}`;
  return value.startsWith("http") ? value : `https://${value}`;
}

function AvailBadge({ availability, color }: { availability?: string; color: string }) {
  if (!availability) return null;
  const map: Record<string, { dot: string; text: string }> = {
    available: { dot: "bg-emerald-400", text: "Open to opportunities" },
    limited:   { dot: "bg-amber-400",   text: "Limited availability" },
    unavailable: { dot: "bg-red-400",   text: "Not available" },
  };
  const m = map[availability];
  if (!m) return null;
  return (
    <span className="inline-flex items-center gap-1.5 rounded-full border px-3 py-1 text-xs font-medium"
      style={{ borderColor: `${color}30`, background: `${color}10`, color }}>
      <span className={`h-1.5 w-1.5 rounded-full ${m.dot}`} />
      {m.text}
    </span>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// CANVAS — Clean editorial white, project grid, suits designers & SMEs
// ─────────────────────────────────────────────────────────────────────────────

export function CanvasPortfolio({ data, accentColor = "#0ea5e9" }: PortfolioProps) {
  const { fullName, headline, bio, avatarUrl, projects, skills, experience,
    socialLinks, contacts, testimonials, availability, resumeUrl } = data;
  const featured = projects.filter(p => p.featured).slice(0, 3);
  const rest = projects.filter(p => !p.featured).slice(0, 6);

  return (
    <main className="min-h-screen bg-white text-neutral-900">
      {/* Nav */}
      <header className="sticky top-0 z-40 border-b border-neutral-100 bg-white/90 backdrop-blur-sm">
        <div className="mx-auto flex max-w-5xl items-center justify-between px-6 py-4">
          <div className="h-7 w-7 rounded-lg" style={{ background: accentColor }} />
          <nav className="hidden items-center gap-8 sm:flex">
            {["Work", "About", "Experience", "Contact"].map(item => (
              <a key={item} href={`#${item.toLowerCase()}`}
                className="text-sm text-neutral-500 hover:text-neutral-900 transition-colors">
                {item}
              </a>
            ))}
          </nav>
          {resumeUrl && (
            <a href={resumeUrl} target="_blank" rel="noopener noreferrer"
              className="rounded-lg px-4 py-2 text-sm font-semibold text-white transition-all hover:opacity-90"
              style={{ background: accentColor }}>
              Download CV
            </a>
          )}
        </div>
      </header>

      {/* Hero */}
      <section className="border-b border-neutral-100 px-6 py-20">
        <div className="mx-auto max-w-5xl">
          <div className="flex flex-col gap-8 md:flex-row md:items-center">
            {avatarUrl && (
              <div className="relative h-24 w-24 shrink-0 overflow-hidden rounded-2xl shadow-xl">
                <Image src={avatarUrl} alt={fullName} fill className="object-cover" sizes="96px" priority />
              </div>
            )}
            <div className="flex-1">
              <div className="mb-4">
                <AvailBadge availability={availability} color={accentColor} />
              </div>
              <h1 className="text-4xl font-black tracking-tight md:text-5xl">{fullName}</h1>
              <p className="mt-2 text-xl font-medium" style={{ color: accentColor }}>{headline}</p>
              <p className="mt-3 max-w-xl text-neutral-500 leading-relaxed">{bio}</p>
              <div className="mt-5 flex flex-wrap gap-3">
                {contacts.map((c, i) => (
                  <a key={i} href={contactHref(c.type, c.value)}
                    className="flex items-center gap-1.5 rounded-lg border border-neutral-200 px-4 py-2 text-sm font-medium text-neutral-600 hover:border-neutral-300 hover:bg-neutral-50 transition-all">
                    {c.label ?? c.value}
                  </a>
                ))}
                {socialLinks.slice(0, 4).map((s, i) => (
                  <a key={i} href={s.url} target="_blank" rel="noopener noreferrer"
                    className="flex items-center gap-1.5 rounded-lg border border-neutral-200 px-4 py-2 text-sm font-medium text-neutral-600 hover:border-neutral-300 hover:bg-neutral-50 transition-all">
                    {s.label ?? s.platform}
                  </a>
                ))}
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Featured work */}
      {featured.length > 0 && (
        <section id="work" className="border-b border-neutral-100 px-6 py-16">
          <div className="mx-auto max-w-5xl">
            <div className="mb-8 flex items-end justify-between">
              <h2 className="text-2xl font-black">Featured Work</h2>
              <span className="text-sm text-neutral-400">{projects.length} projects total</span>
            </div>
            <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
              {featured.map(p => (
                <div key={p.id} className="group overflow-hidden rounded-2xl border border-neutral-100 shadow-sm hover:shadow-lg transition-all">
                  <div className="relative aspect-video overflow-hidden bg-neutral-100">
                    <Image src={p.coverImageUrl} alt={p.title} fill
                      className="object-cover transition-transform duration-700 group-hover:scale-105" sizes="400px" />
                  </div>
                  <div className="p-5">
                    <div className="mb-2 flex flex-wrap gap-1">
                      {p.tags.slice(0, 3).map((t, i) => (
                        <span key={i} className="rounded-md px-2 py-0.5 text-xs font-medium text-neutral-500"
                          style={{ background: `${accentColor}10`, color: accentColor }}>
                          {t}
                        </span>
                      ))}
                    </div>
                    <h3 className="font-bold text-neutral-900">{p.title}</h3>
                    <p className="mt-1 text-sm text-neutral-500 line-clamp-2">{p.description}</p>
                    <div className="mt-3 flex items-center gap-3">
                      {p.liveUrl && (
                        <a href={p.liveUrl} target="_blank" rel="noopener noreferrer"
                          className="flex items-center gap-1 text-xs font-semibold transition-colors"
                          style={{ color: accentColor }}>
                          <ExternalArrow size={12} /> Live
                        </a>
                      )}
                      {p.repoUrl && (
                        <a href={p.repoUrl} target="_blank" rel="noopener noreferrer"
                          className="flex items-center gap-1 text-xs font-medium text-neutral-400 hover:text-neutral-700 transition-colors">
                          Code
                        </a>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* All projects list */}
      {rest.length > 0 && (
        <section className="border-b border-neutral-100 bg-neutral-50 px-6 py-16">
          <div className="mx-auto max-w-5xl">
            <h2 className="mb-6 text-2xl font-black">More Projects</h2>
            <div className="grid gap-3 md:grid-cols-2">
              {rest.map(p => (
                <div key={p.id} className="flex items-start gap-4 rounded-xl border border-neutral-200 bg-white p-4 hover:shadow-sm transition-all">
                  <div className="relative h-14 w-14 shrink-0 overflow-hidden rounded-lg bg-neutral-100">
                    <Image src={p.coverImageUrl} alt={p.title} fill className="object-cover" sizes="56px" />
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-start justify-between gap-2">
                      <h3 className="font-semibold text-neutral-900">{p.title}</h3>
                      <div className="flex shrink-0 gap-2">
                        {p.liveUrl && (
                          <a href={p.liveUrl} target="_blank" rel="noopener noreferrer"
                            className="text-xs font-semibold" style={{ color: accentColor }}>
                            Live ↗
                          </a>
                        )}
                      </div>
                    </div>
                    <p className="mt-0.5 text-xs text-neutral-500 line-clamp-1">{p.description}</p>
                    <div className="mt-1.5 flex flex-wrap gap-1">
                      {p.tags.slice(0, 3).map((t, i) => (
                        <span key={i} className="rounded bg-neutral-100 px-1.5 py-0.5 text-xs text-neutral-500">{t}</span>
                      ))}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Skills */}
      {data.skills.length > 0 && (
        <section id="about" className="border-b border-neutral-100 bg-white px-6 py-16">
          <div className="mx-auto max-w-5xl">
            <h2 className="mb-8 text-2xl font-black">Skills & Stack</h2>
            <div className="grid gap-6 sm:grid-cols-2 md:grid-cols-3">
              {data.skills.map((group, i) => (
                <div key={i}>
                  <h3 className="mb-3 text-sm font-bold text-neutral-700">{group.category}</h3>
                  <div className="flex flex-wrap gap-1.5">
                    {group.items.map((item, j) => (
                      <span key={j} className="rounded-lg border border-neutral-200 px-2.5 py-1 text-xs text-neutral-600">
                        {item}
                      </span>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Experience */}
      {experience.length > 0 && (
        <section id="experience" className="border-b border-neutral-100 bg-neutral-50 px-6 py-16">
          <div className="mx-auto max-w-5xl">
            <h2 className="mb-8 text-2xl font-black">Experience</h2>
            <div className="space-y-6">
              {experience.map((e, i) => (
                <div key={i} className="flex gap-5 rounded-2xl border border-neutral-200 bg-white p-5">
                  {e.logoUrl && (
                    <div className="relative h-10 w-10 shrink-0 overflow-hidden rounded-lg border border-neutral-100">
                      <Image src={e.logoUrl} alt={e.company} fill className="object-contain p-1" sizes="40px" />
                    </div>
                  )}
                  <div className="flex-1">
                    <div className="flex flex-wrap items-baseline gap-2">
                      <h3 className="font-bold text-neutral-900">{e.role}</h3>
                      <span className="text-sm text-neutral-500">@ {e.company}</span>
                    </div>
                    <p className="mt-0.5 text-xs text-neutral-400">
                      {e.startDate.slice(0, 7)} – {e.endDate ? e.endDate.slice(0, 7) : "Present"}
                      {e.location && ` · ${e.location}`}
                    </p>
                    <p className="mt-2 text-sm text-neutral-600 leading-relaxed">{e.description}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Testimonials */}
      {testimonials && testimonials.length > 0 && (
        <section className="border-b border-neutral-100 bg-white px-6 py-16">
          <div className="mx-auto max-w-5xl">
            <h2 className="mb-8 text-2xl font-black">Testimonials</h2>
            <div className="grid gap-5 md:grid-cols-2">
              {testimonials.slice(0, 4).map((t, i) => (
                <div key={i} className="rounded-2xl bg-neutral-50 border border-neutral-100 p-5">
                  <div className="mb-3 flex">
                    {Array.from({ length: 5 }).map((_, j) => (
                      <span key={j} className="text-amber-400 text-sm">★</span>
                    ))}
                  </div>
                  <p className="text-sm leading-relaxed text-neutral-600 italic">&ldquo;{t.text}&rdquo;</p>
                  <div className="mt-4 flex items-center gap-3">
                    {t.avatarUrl && (
                      <div className="relative h-8 w-8 overflow-hidden rounded-full">
                        <Image src={t.avatarUrl} alt={t.author} fill className="object-cover" sizes="32px" />
                      </div>
                    )}
                    <div>
                      <p className="text-xs font-bold text-neutral-800">{t.author}</p>
                      <p className="text-xs text-neutral-400">{t.role} · {t.company}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Contact footer */}
      <footer id="contact" className="px-6 py-12 bg-white">
        <div className="mx-auto max-w-5xl flex flex-wrap items-center justify-between gap-4">
          <div>
            <h2 className="text-xl font-black">Let's work together</h2>
            <div className="mt-2 flex flex-wrap gap-3">
              {contacts.map((c, i) => (
                <a key={i} href={contactHref(c.type, c.value)}
                  className="text-sm font-medium transition-colors hover:opacity-70" style={{ color: accentColor }}>
                  {c.value}
                </a>
              ))}
            </div>
          </div>
          <div className="flex gap-3 flex-wrap">
            {socialLinks.map((s, i) => (
              <a key={i} href={s.url} target="_blank" rel="noopener noreferrer"
                className="text-sm font-medium text-neutral-400 hover:text-neutral-900 transition-colors">
                {s.label ?? s.platform}
              </a>
            ))}
          </div>
        </div>
        <p className="mx-auto max-w-5xl mt-6 text-xs text-neutral-300">PresenceCard</p>
      </footer>
    </main>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// STUDIO — Cinematic dark, full-bleed project visuals, agency/photographer feel
// ─────────────────────────────────────────────────────────────────────────────

export function StudioPortfolio({ data, accentColor = "#ec4899" }: PortfolioProps) {
  const { fullName, headline, bio, avatarUrl, projects, skills, experience, socialLinks, contacts, resumeUrl, availability } = data;

  return (
    <main className="min-h-screen bg-zinc-950 text-white">
      {/* Hero */}
      <section className="relative min-h-[85vh] flex flex-col justify-end px-6 pb-16 overflow-hidden">
        {projects[0]?.coverImageUrl && (
          <div className="absolute inset-0">
            <Image src={projects[0].coverImageUrl} alt="Hero" fill className="object-cover opacity-25" sizes="100vw" priority />
            <div className="absolute inset-0" style={{ background: "linear-gradient(to top, #09090b 40%, transparent 100%)" }} />
          </div>
        )}
        <div className="relative z-10 mx-auto max-w-5xl w-full">
          <div className="flex items-end justify-between flex-wrap gap-6">
            <div>
              <AvailBadge availability={availability} color={accentColor} />
              <h1 className="mt-3 text-6xl font-black leading-none tracking-tighter md:text-8xl">{fullName}</h1>
              <p className="mt-2 text-xl text-zinc-400 max-w-xl">{headline}</p>
            </div>
            <div className="flex flex-col items-end gap-3">
              {avatarUrl && (
                <div className="relative h-16 w-16 overflow-hidden rounded-full border-2 border-white/10">
                  <Image src={avatarUrl} alt={fullName} fill className="object-cover" sizes="64px" />
                </div>
              )}
              {resumeUrl && (
                <a href={resumeUrl} target="_blank" rel="noopener noreferrer"
                  className="rounded-full px-5 py-2 text-sm font-semibold text-white border border-white/20 hover:bg-white/10 transition-all">
                  View CV
                </a>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* About */}
      <section className="border-t border-zinc-800 px-6 py-16">
        <div className="mx-auto max-w-5xl grid md:grid-cols-2 gap-12 items-center">
          <p className="text-lg leading-relaxed text-zinc-400">{bio}</p>
          <div className="flex flex-wrap gap-2">
            {contacts.map((c, i) => (
              <a key={i} href={contactHref(c.type, c.value)}
                className="rounded-full border border-zinc-700 px-4 py-2 text-sm text-zinc-400 hover:border-zinc-500 hover:text-white transition-all">
                {c.label ?? c.value}
              </a>
            ))}
            {socialLinks.slice(0, 3).map((s, i) => (
              <a key={i} href={s.url} target="_blank" rel="noopener noreferrer"
                className="rounded-full border border-zinc-700 px-4 py-2 text-sm text-zinc-400 hover:border-zinc-500 hover:text-white transition-all">
                {s.label ?? s.platform}
              </a>
            ))}
          </div>
        </div>
      </section>

      {/* Projects grid */}
      <section className="border-t border-zinc-800 px-6 py-16">
        <div className="mx-auto max-w-5xl">
          <div className="mb-10 flex items-center justify-between">
            <h2 className="text-3xl font-black">Selected Work</h2>
            <span className="text-sm text-zinc-600">{projects.length} projects</span>
          </div>
          <div className="grid gap-6 md:grid-cols-2">
            {projects.slice(0, 6).map(p => (
              <div key={p.id} className="group relative overflow-hidden rounded-2xl bg-zinc-900 cursor-pointer">
                <div className="relative aspect-[4/3] overflow-hidden">
                  <Image src={p.coverImageUrl} alt={p.title} fill
                    className="object-cover opacity-70 group-hover:opacity-100 group-hover:scale-105 transition-all duration-700" sizes="600px" />
                </div>
                <div className="absolute inset-0 flex flex-col justify-end bg-gradient-to-t from-zinc-950/90 to-transparent p-5">
                  <div className="flex flex-wrap gap-1 mb-2">
                    {p.tags.slice(0, 2).map((t, i) => (
                      <span key={i} className="rounded-full border border-white/20 px-2 py-0.5 text-xs text-white/60">{t}</span>
                    ))}
                  </div>
                  <h3 className="text-lg font-black">{p.title}</h3>
                  <p className="mt-1 text-sm text-zinc-400 line-clamp-1">{p.description}</p>
                  <div className="mt-2 flex gap-3 opacity-0 group-hover:opacity-100 transition-opacity">
                    {p.liveUrl && (
                      <a href={p.liveUrl} target="_blank" rel="noopener noreferrer"
                        className="text-xs font-semibold" style={{ color: accentColor }}>
                        Live ↗
                      </a>
                    )}
                    {p.repoUrl && (
                      <a href={p.repoUrl} target="_blank" rel="noopener noreferrer"
                        className="text-xs text-zinc-400">Repo</a>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Skills */}
      {data.skills.length > 0 && (
        <section className="border-t border-zinc-800 px-6 py-16">
          <div className="mx-auto max-w-5xl">
            <h2 className="mb-8 text-3xl font-black">Craft</h2>
            <div className="grid gap-5 sm:grid-cols-2 md:grid-cols-3">
              {data.skills.map((g, i) => (
                <div key={i} className="rounded-xl border border-zinc-800 bg-zinc-900 p-5">
                  <h3 className="mb-3 text-xs font-bold uppercase tracking-wider" style={{ color: accentColor }}>{g.category}</h3>
                  <div className="flex flex-wrap gap-1.5">
                    {g.items.map((item, j) => (
                      <span key={j} className="rounded-md bg-zinc-800 px-2.5 py-1 text-xs text-zinc-400">{item}</span>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Experience */}
      {experience.length > 0 && (
        <section className="border-t border-zinc-800 px-6 py-16">
          <div className="mx-auto max-w-5xl">
            <h2 className="mb-8 text-3xl font-black">Experience</h2>
            <div className="space-y-5">
              {experience.map((e, i) => (
                <div key={i} className="flex items-start gap-4 rounded-xl border border-zinc-800 p-5">
                  <div>
                    <div className="flex flex-wrap items-baseline gap-2">
                      <h3 className="font-bold">{e.role}</h3>
                      <span className="text-sm text-zinc-500">@ {e.company}</span>
                    </div>
                    <p className="text-xs text-zinc-600 mt-0.5">{e.startDate.slice(0, 7)} – {e.endDate ? e.endDate.slice(0, 7) : "Present"}{e.location && ` · ${e.location}`}</p>
                    <p className="mt-2 text-sm text-zinc-400 leading-relaxed">{e.description}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      <footer className="border-t border-zinc-800 px-6 py-10 flex flex-wrap justify-between items-center gap-4">
        <p className="text-zinc-700 font-bold">{fullName}</p>
        <div className="flex gap-4 flex-wrap">
          {socialLinks.map((s, i) => (
            <a key={i} href={s.url} target="_blank" rel="noopener noreferrer"
              className="text-sm text-zinc-600 hover:text-white transition-colors">
              {s.label ?? s.platform}
            </a>
          ))}
        </div>
        <p className="text-xs text-zinc-800">PresenceCard</p>
      </footer>
    </main>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// FORGE — Terminal/developer aesthetic, perfect for engineers & open source
// ─────────────────────────────────────────────────────────────────────────────

export function ForgePortfolio({ data, accentColor = "#22c55e" }: PortfolioProps) {
  const { fullName, headline, bio, projects, skills, experience, socialLinks, contacts, availability, resumeUrl } = data;

  return (
    <main className="min-h-screen bg-neutral-950 text-neutral-300" style={{ fontFamily: "'JetBrains Mono', 'Fira Code', monospace" }}>
      {/* Terminal window header */}
      <div className="sticky top-0 z-40 border-b border-neutral-800 bg-neutral-950/95 backdrop-blur-sm">
        <div className="mx-auto flex max-w-4xl items-center justify-between px-6 py-3">
          <div className="flex items-center gap-3">
            <div className="flex gap-1.5">
              <span className="h-3 w-3 rounded-full bg-red-500/80" />
              <span className="h-3 w-3 rounded-full bg-amber-500/80" />
              <span className="h-3 w-3 rounded-full bg-emerald-500/80" />
            </div>
            <span className="text-xs text-neutral-600">{fullName.toLowerCase().replace(/ /g, "-")}.portfolio</span>
          </div>
          <div className="flex gap-4">
            {contacts.slice(0, 2).map((c, i) => (
              <a key={i} href={contactHref(c.type, c.value)}
                className="text-xs text-neutral-600 hover:text-white transition-colors">
                [{c.label ?? c.type}]
              </a>
            ))}
            {resumeUrl && (
              <a href={resumeUrl} target="_blank" rel="noopener noreferrer"
                className="text-xs" style={{ color: accentColor }}>
                [resume.pdf]
              </a>
            )}
          </div>
        </div>
      </div>

      <div className="mx-auto max-w-4xl px-6 py-14">
        {/* Prompt header */}
        <div className="mb-10">
          <div className="flex items-center gap-2 mb-3">
            <span style={{ color: accentColor }}>❯</span>
            <span className="text-neutral-600 text-sm">whoami</span>
          </div>
          <h1 className="text-4xl font-bold text-white">{fullName}</h1>
          <p className="mt-1 text-lg" style={{ color: accentColor }}>{headline}</p>
          <p className="mt-3 text-sm leading-relaxed text-neutral-500 max-w-xl">{bio}</p>
          <div className="mt-4 flex flex-wrap gap-2">
            <AvailBadge availability={availability} color={accentColor} />
          </div>
        </div>

        {/* Contact JSON block */}
        {contacts.length > 0 && (
          <div className="mb-10">
            <div className="flex items-center gap-2 mb-3">
              <span style={{ color: accentColor }}>❯</span>
              <span className="text-neutral-600 text-sm">cat contacts.json</span>
            </div>
            <div className="rounded-xl border border-neutral-800 bg-neutral-900/60 p-5">
              <p className="text-neutral-700">{"{"}</p>
              {contacts.map((c, i) => (
                <div key={i} className="ml-4 py-0.5">
                  <span className="text-sky-400">&quot;{c.label ?? c.type}&quot;</span>
                  <span className="text-neutral-600">: </span>
                  <a href={contactHref(c.type, c.value)}
                    className="transition-colors hover:opacity-70" style={{ color: accentColor }}>
                    &quot;{c.value}&quot;
                  </a>
                  {i < contacts.length - 1 && <span className="text-neutral-700">,</span>}
                </div>
              ))}
              <p className="text-neutral-700">{"}"}</p>
            </div>
          </div>
        )}

        {/* Projects */}
        {projects.length > 0 && (
          <div className="mb-10">
            <div className="flex items-center gap-2 mb-4">
              <span style={{ color: accentColor }}>❯</span>
              <span className="text-neutral-600 text-sm">ls ~/projects/ --sort=stars</span>
            </div>
            <div className="space-y-3">
              {projects.slice(0, 8).map(p => (
                <div key={p.id} className="group rounded-xl border border-neutral-800 bg-neutral-900/40 p-4 transition-all hover:border-neutral-700">
                  <div className="flex items-start justify-between gap-4">
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-3 flex-wrap">
                        <h3 className="font-bold text-white">{p.title}</h3>
                        {p.featured && (
                          <span className="rounded-full px-2 py-0.5 text-xs font-bold"
                            style={{ background: `${accentColor}20`, color: accentColor }}>
                            featured
                          </span>
                        )}
                      </div>
                      <p className="mt-1 text-xs text-neutral-500 line-clamp-1">{p.description}</p>
                      <div className="mt-2 flex flex-wrap gap-1.5">
                        {p.tags.map((t, i) => (
                          <span key={i} className="text-xs" style={{ color: accentColor }}>#{t}</span>
                        ))}
                      </div>
                    </div>
                    <div className="flex gap-3 shrink-0 text-xs opacity-60 group-hover:opacity-100 transition-opacity">
                      {p.liveUrl && (
                        <a href={p.liveUrl} target="_blank" rel="noopener noreferrer"
                          className="hover:text-white transition-colors">[live]</a>
                      )}
                      {p.repoUrl && (
                        <a href={p.repoUrl} target="_blank" rel="noopener noreferrer"
                          className="hover:text-white transition-colors">[repo]</a>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Skills */}
        {data.skills.length > 0 && (
          <div className="mb-10">
            <div className="flex items-center gap-2 mb-4">
              <span style={{ color: accentColor }}>❯</span>
              <span className="text-neutral-600 text-sm">cat skills.yaml</span>
            </div>
            <div className="space-y-2">
              {data.skills.map((g, i) => (
                <div key={i} className="flex gap-4 text-sm flex-wrap">
                  <span className="w-32 shrink-0 text-right text-neutral-600">{g.category}:</span>
                  <span className="text-neutral-400">{g.items.join(" · ")}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Experience */}
        {experience.length > 0 && (
          <div className="mb-10">
            <div className="flex items-center gap-2 mb-4">
              <span style={{ color: accentColor }}>❯</span>
              <span className="text-neutral-600 text-sm">cat experience.log</span>
            </div>
            <div className="space-y-4 border-l border-neutral-800 pl-4">
              {experience.map((e, i) => (
                <div key={i}>
                  <div className="flex flex-wrap items-baseline gap-2">
                    <span className="font-bold text-white">{e.role}</span>
                    <span className="text-neutral-600">@{e.company}</span>
                    <span className="text-xs text-neutral-700">{e.startDate.slice(0, 7)}–{e.endDate ? e.endDate.slice(0, 7) : "now"}</span>
                  </div>
                  <p className="mt-1 text-xs text-neutral-500 leading-relaxed">{e.description}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Social */}
        <div className="mb-10">
          <div className="flex items-center gap-2 mb-3">
            <span style={{ color: accentColor }}>❯</span>
            <span className="text-neutral-600 text-sm">open ./links/</span>
          </div>
          <div className="flex flex-wrap gap-2">
            {socialLinks.map((s, i) => (
              <a key={i} href={s.url} target="_blank" rel="noopener noreferrer"
                className="rounded-lg border border-neutral-800 px-3 py-1.5 text-xs text-neutral-500 hover:border-neutral-600 hover:text-white transition-all">
                [{s.label ?? s.platform}]
              </a>
            ))}
          </div>
        </div>

        <div className="flex items-center gap-2 text-xs text-neutral-800">
          <span style={{ color: accentColor }}>✓</span>
          <span>powered by PresenceCard</span>
        </div>
      </div>
    </main>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// SPECTRUM — Bold bento grid, color blocks, creative directors & brand designers
// ─────────────────────────────────────────────────────────────────────────────

export function SpectrumPortfolio({ data, accentColor = "#f59e0b" }: PortfolioProps) {
  const { fullName, headline, bio, avatarUrl, projects, skills, socialLinks, contacts, gallery, resumeUrl, availability } = data;

  return (
    <main className="min-h-screen bg-white text-zinc-900">
      {/* Hero — big type + photo bento */}
      <section className="px-6 py-16 border-b-4 border-zinc-900">
        <div className="mx-auto max-w-5xl">
          <div className="mb-4 flex items-center gap-3">
            <div className="h-2 w-10 rounded-full" style={{ background: accentColor }} />
            <AvailBadge availability={availability} color={accentColor} />
          </div>
          <div className="grid gap-8 md:grid-cols-2 items-center">
            <div>
              <h1 className="text-5xl font-black leading-none tracking-tighter md:text-7xl">{fullName}</h1>
              <p className="mt-3 text-xl font-bold text-zinc-500">{headline}</p>
              <p className="mt-4 leading-relaxed text-zinc-500 max-w-sm">{bio}</p>
              <div className="mt-6 flex flex-wrap gap-2">
                {contacts.map((c, i) => (
                  <a key={i} href={contactHref(c.type, c.value)}
                    className="rounded-full border-2 border-zinc-900 px-4 py-2 text-sm font-bold hover:bg-zinc-900 hover:text-white transition-all">
                    {c.label ?? c.value}
                  </a>
                ))}
                {resumeUrl && (
                  <a href={resumeUrl} target="_blank" rel="noopener noreferrer"
                    className="rounded-full px-4 py-2 text-sm font-bold text-white transition-all hover:opacity-90"
                    style={{ background: accentColor }}>
                    Resume
                  </a>
                )}
              </div>
            </div>
            {avatarUrl && (
              <div className="relative aspect-square max-w-xs overflow-hidden rounded-3xl border-4 border-zinc-900 mx-auto md:mx-0">
                <Image src={avatarUrl} alt={fullName} fill className="object-cover" sizes="320px" priority />
              </div>
            )}
          </div>
        </div>
      </section>

      {/* Bento projects grid */}
      {projects.length > 0 && (
        <section className="border-b-4 border-zinc-900 px-6 py-16">
          <div className="mx-auto max-w-5xl">
            <h2 className="mb-8 text-3xl font-black">Work</h2>
            <div className="grid grid-cols-2 gap-4 md:grid-cols-3">
              {projects.slice(0, 6).map((p, i) => (
                <div key={p.id} className={`group overflow-hidden rounded-2xl border-2 border-zinc-900 ${i === 0 ? "col-span-2 row-span-2" : ""}`}>
                  <div className={`relative overflow-hidden bg-zinc-100 ${i === 0 ? "aspect-[4/3]" : "aspect-square"}`}>
                    <Image src={p.coverImageUrl} alt={p.title} fill
                      className="object-cover group-hover:scale-105 transition-transform duration-700" sizes="400px" />
                  </div>
                  <div className="border-t-2 border-zinc-900 p-3">
                    <h3 className="font-black text-sm leading-tight">{p.title}</h3>
                    <div className="mt-1 flex gap-2">
                      {p.liveUrl && (
                        <a href={p.liveUrl} target="_blank" rel="noopener noreferrer"
                          className="text-xs font-bold" style={{ color: accentColor }}>Live ↗</a>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Skills — color coded categories */}
      {data.skills.length > 0 && (
        <section className="border-b-4 border-zinc-900 bg-zinc-950 px-6 py-16">
          <div className="mx-auto max-w-5xl">
            <h2 className="mb-8 text-3xl font-black text-white">Stack</h2>
            <div className="grid gap-4 sm:grid-cols-2 md:grid-cols-3">
              {data.skills.map((g, i) => {
                const colors = [accentColor, "#6366f1", "#ec4899", "#22c55e", "#0ea5e9", "#f97316"];
                const c = colors[i % colors.length];
                return (
                  <div key={i} className="rounded-2xl p-5 text-white" style={{ background: `${c}20`, border: `1px solid ${c}30` }}>
                    <h3 className="mb-3 text-xs font-bold uppercase tracking-wider" style={{ color: c }}>{g.category}</h3>
                    <div className="flex flex-wrap gap-1.5">
                      {g.items.map((item, j) => (
                        <span key={j} className="rounded-lg px-2.5 py-1 text-xs font-medium text-white/70"
                          style={{ background: "rgba(255,255,255,0.08)" }}>
                          {item}
                        </span>
                      ))}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </section>
      )}

      {/* Gallery masonry */}
      {gallery && gallery.length > 0 && (
        <section className="border-b-4 border-zinc-900 px-6 py-16">
          <div className="mx-auto max-w-5xl">
            <h2 className="mb-8 text-3xl font-black">Gallery</h2>
            <div className="columns-2 gap-3 md:columns-3">
              {gallery.slice(0, 9).map((img, i) => (
                <div key={i} className="mb-3 overflow-hidden rounded-xl border-2 border-zinc-900 break-inside-avoid">
                  <div className="relative aspect-square">
                    <Image src={img.url} alt={img.alt} fill className="object-cover" sizes="300px" />
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      <footer className="border-t-2 border-zinc-200 px-6 py-8 flex flex-wrap justify-between items-center gap-4">
        <div className="flex gap-4 flex-wrap">
          {socialLinks.map((s, i) => (
            <a key={i} href={s.url} target="_blank" rel="noopener noreferrer"
              className="text-sm font-semibold text-zinc-400 hover:text-zinc-900 transition-colors">
              {s.label ?? s.platform}
            </a>
          ))}
        </div>
        <p className="text-xs text-zinc-300">PresenceCard</p>
      </footer>
    </main>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// BLUEPRINT — Technical grid, suits architects, consultants, engineers
// ─────────────────────────────────────────────────────────────────────────────

export function BlueprintPortfolio({ data, accentColor = "#3b82f6" }: PortfolioProps) {
  const { fullName, headline, bio, projects, skills, experience, socialLinks, contacts, availability, resumeUrl } = data;

  return (
    <main className="min-h-screen text-slate-200" style={{
      background: "#06101f",
      backgroundImage: `
        linear-gradient(rgba(59,130,246,0.06) 1px, transparent 1px),
        linear-gradient(90deg, rgba(59,130,246,0.06) 1px, transparent 1px)`,
      backgroundSize: "32px 32px",
    }}>
      <div className="mx-auto max-w-5xl px-6 py-14">

        {/* Header panel */}
        <div className="mb-10 rounded-2xl border p-8" style={{ borderColor: `${accentColor}30`, background: `${accentColor}06` }}>
          <div className="flex items-start justify-between gap-6 flex-wrap">
            <div>
              <p className="text-xs font-semibold uppercase tracking-[0.3em] mb-2" style={{ color: `${accentColor}80` }}>
                // PROFESSIONAL PROFILE
              </p>
              <h1 className="text-4xl font-black text-white">{fullName}</h1>
              <p className="mt-1 text-xl text-slate-400">{headline}</p>
              <AvailBadge availability={availability} color={accentColor} />
            </div>
            <div className="space-y-2">
              {contacts.map((c, i) => (
                <a key={i} href={contactHref(c.type, c.value)}
                  className="flex items-center gap-2 text-sm text-slate-400 hover:text-white transition-colors">
                  <span style={{ color: accentColor }}>→</span> {c.value}
                </a>
              ))}
              {resumeUrl && (
                <a href={resumeUrl} target="_blank" rel="noopener noreferrer"
                  className="flex items-center gap-2 text-sm transition-colors hover:opacity-80" style={{ color: accentColor }}>
                  <span>→</span> resume.pdf
                </a>
              )}
            </div>
          </div>
          <p className="mt-5 text-sm leading-relaxed text-slate-400 max-w-2xl border-t pt-5" style={{ borderColor: `${accentColor}20` }}>
            {bio}
          </p>
        </div>

        {/* Section divider helper */}
        {(label: string) => (
          <div className="mb-5 flex items-center gap-3">
            <div className="h-px flex-1" style={{ background: `${accentColor}30` }} />
            <span className="text-xs font-semibold uppercase tracking-widest" style={{ color: `${accentColor}80` }}>{label}</span>
            <div className="h-px flex-1" style={{ background: `${accentColor}30` }} />
          </div>
        )}

        {/* Projects */}
        {projects.length > 0 && (
          <div className="mb-10">
            <div className="mb-5 flex items-center gap-3">
              <div className="h-px flex-1" style={{ background: `${accentColor}25` }} />
              <span className="text-xs font-semibold uppercase tracking-widest" style={{ color: `${accentColor}70` }}>Projects</span>
              <div className="h-px flex-1" style={{ background: `${accentColor}25` }} />
            </div>
            <div className="grid gap-4 md:grid-cols-2">
              {projects.slice(0, 6).map(p => (
                <div key={p.id} className="group rounded-xl border p-4 transition-all hover:border-blue-500/30"
                  style={{ borderColor: `${accentColor}15`, background: `${accentColor}04` }}>
                  <h3 className="font-bold text-white">{p.title}</h3>
                  <p className="mt-1 text-xs text-slate-500 line-clamp-2">{p.description}</p>
                  <div className="mt-2 flex flex-wrap gap-1.5">
                    {p.tags.map((t, i) => (
                      <span key={i} className="rounded px-1.5 py-0.5 text-xs font-mono"
                        style={{ color: accentColor, background: `${accentColor}15` }}>
                        #{t}
                      </span>
                    ))}
                  </div>
                  <div className="mt-2.5 flex gap-4">
                    {p.liveUrl && (
                      <a href={p.liveUrl} target="_blank" rel="noopener noreferrer"
                        className="text-xs font-medium transition-colors hover:opacity-70" style={{ color: accentColor }}>
                        Live ↗
                      </a>
                    )}
                    {p.repoUrl && (
                      <a href={p.repoUrl} target="_blank" rel="noopener noreferrer"
                        className="text-xs font-medium text-slate-500 hover:text-white transition-colors">
                        Repo
                      </a>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Skills */}
        {data.skills.length > 0 && (
          <div className="mb-10">
            <div className="mb-5 flex items-center gap-3">
              <div className="h-px flex-1" style={{ background: `${accentColor}25` }} />
              <span className="text-xs font-semibold uppercase tracking-widest" style={{ color: `${accentColor}70` }}>Stack</span>
              <div className="h-px flex-1" style={{ background: `${accentColor}25` }} />
            </div>
            <div className="grid gap-3 sm:grid-cols-2 md:grid-cols-3">
              {data.skills.map((g, i) => (
                <div key={i} className="rounded-xl border p-4" style={{ borderColor: `${accentColor}12`, background: `${accentColor}04` }}>
                  <p className="mb-2 text-xs font-bold uppercase tracking-wider" style={{ color: accentColor }}>{g.category}</p>
                  <p className="text-xs text-slate-500 leading-relaxed">{g.items.join(" · ")}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Experience timeline */}
        {experience.length > 0 && (
          <div className="mb-10">
            <div className="mb-5 flex items-center gap-3">
              <div className="h-px flex-1" style={{ background: `${accentColor}25` }} />
              <span className="text-xs font-semibold uppercase tracking-widest" style={{ color: `${accentColor}70` }}>Experience</span>
              <div className="h-px flex-1" style={{ background: `${accentColor}25` }} />
            </div>
            <div className="relative border-l pl-6" style={{ borderColor: `${accentColor}20` }}>
              {experience.map((e, i) => (
                <div key={i} className="mb-6 relative">
                  <div className="absolute -left-8 top-1 h-3 w-3 rounded-full border-2"
                    style={{ background: "#06101f", borderColor: accentColor }} />
                  <div className="flex flex-wrap items-baseline gap-2 mb-1">
                    <h3 className="font-bold text-white">{e.role}</h3>
                    <span className="text-sm text-slate-500">@ {e.company}</span>
                    <span className="text-xs text-slate-700 font-mono">
                      {e.startDate.slice(0, 7)}—{e.endDate ? e.endDate.slice(0, 7) : "present"}
                    </span>
                  </div>
                  <p className="text-sm text-slate-500 leading-relaxed">{e.description}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Social links */}
        <footer className="border-t pt-6 flex flex-wrap justify-between items-center gap-4" style={{ borderColor: `${accentColor}20` }}>
          <div className="flex flex-wrap gap-3">
            {socialLinks.map((s, i) => (
              <a key={i} href={s.url} target="_blank" rel="noopener noreferrer"
                className="text-xs font-mono text-slate-600 hover:text-white transition-colors">
                {s.label ?? s.platform}
              </a>
            ))}
          </div>
          <p className="text-xs font-mono text-slate-800">// PresenceCard</p>
        </footer>
      </div>
    </main>
  );
}
